#!/usr/bin/env bash
# Android build. Requires Android Studio (or Android SDK + NDK 26) and a
# JDK 17. The Gradle wrapper is generated by Android Studio on first open;
# alternatively install Gradle 8.7+ and run: gradle wrapper
set -euo pipefail
cd "$(dirname "$0")/../editor"

if [ -z "${ANDROID_HOME:-}" ] && [ -z "${ANDROID_SDK_ROOT:-}" ]; then
  echo "ERROR: ANDROID_HOME is not set. Install Android Studio / SDK first."
  exit 1
fi
if [ ! -x ./gradlew ]; then
  echo "Generating Gradle wrapper (requires Gradle 8.7+ on PATH)..."
  gradle wrapper --gradle-version 8.7
fi
./gradlew :app:assembleDebug
echo "APK: app/build/outputs/apk/debug/app-debug.apk"
